def transform(grid):
    h, w = len(grid), len(grid[0])
    output = [[0]*w for _ in range(h)]

    # Find the pattern row (first row with exactly 6 sevens and a gap at index 5)
    pattern_row_idx = None
    for i, row in enumerate(grid):
        sevent_indices = [j for j, x in enumerate(row) if x == 7]
        if len(sevent_indices) == 6 and 4 in sevent_indices and 5 not in sevent_indices:
            pattern_row_idx = i
            pattern = row[:]
            break

    if pattern_row_idx is not None:
        # Shift pattern down by 4 rows
        shift = 4
        new_pattern_row = pattern_row_idx + shift

        # Fill rows 0 to pattern_row_idx with 3s
        for i in range(pattern_row_idx):
            for j in range(w):
                output[i][j] = 3

        # Fill rows from pattern_row_idx to new_pattern_row-1 with 8s
        for i in range(pattern_row_idx, new_pattern_row):
            for j in range(w):
                output[i][j] = 8

        # Put pattern at new location
        for j in range(w):
            output[new_pattern_row][j] = pattern[j]

        # Fill remaining from new_pattern_row+1 with 3s (preserve original structure from rows after pattern)
        for i in range(new_pattern_row+1, h):
            for j in range(w):
                output[i][j] = grid[i][j] if i < h else 3
    else:
        # No pattern row - copy input as-is, replacing the 2-row with 3s if present
        for i in range(h):
            for j in range(w):
                output[i][j] = grid[i][j]

    return output
